def maxCoins(nums: list[int]) -> int:
    val = [1] + [x for x in nums if x > 0] + [1]
    n = len(val)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + val[i] * val[k] * val[j])
    return dp[0][n - 1]

